const body = $input.first().json.body || $input.first().json;
let numero, mensaje, nombre, timestamp, wa_phone_id, canal, message_id;

// --- Evolution API v1.8.7 / v2.x ---
if (body?.data?.message) {
  const data = body.data;

  // Ignorar mensajes enviados por la propia clinica
  if (data.key?.fromMe === true) {
    return [];
  }

  // remoteJid es el numero del LEAD (quien escribe)
  const remoteJid = data.key?.remoteJidAlt || data.key?.remoteJid || '';

  // Ignorar mensajes de grupos de WhatsApp
  if (remoteJid.includes('@g.us') || remoteJid.includes('-1') || remoteJid.match(/\d+-\d+@/)) {
    return [];
  }

  // Control de duplicados por ID de mensaje
  message_id = data.key?.id || '';

  numero = remoteJid
    .replace('@s.whatsapp.net', '')
    .replace('@lid', '')
    .replace('@g.us', '');

  mensaje = data.message?.conversation || 
            data.message?.extendedTextMessage?.text || 
            data.message?.imageMessage?.caption || '';
  nombre = data.pushName || 'Sin nombre';
  timestamp = body.date_time || new Date().toISOString();
  wa_phone_id = body.instance || data.owner || 'cli_001';
  canal = 'whatsapp';
}
// --- Instagram ---
else if (body?.object === 'instagram' || body?.entry?.[0]?.messaging) {
  const messaging = body.entry[0].messaging[0];
  numero = messaging.sender.id;
  mensaje = messaging.message?.text || '';
  nombre = 'Usuario Instagram';
  timestamp = new Date(messaging.timestamp).toISOString();
  wa_phone_id = body.entry[0].id || '';
  canal = 'instagram';
  message_id = messaging.message?.mid || '';
}
// --- Chat Web ---
else if (body?.canal === 'webchat' || body?.session_id) {
  numero = body.session_id || body.numero;
  mensaje = body.mensaje || body.message || '';
  nombre = body.nombre || body.name || 'Sin nombre';
  timestamp = new Date().toISOString();
  wa_phone_id = body.clinica_id || 'cli_001';
  canal = 'webchat';
  message_id = '';
}
// --- Fallback / testing ---
else {
  numero = body.numero || body.from || 'test';
  mensaje = body.mensaje || body.message || body.text || '';
  nombre = body.nombre || body.name || 'Sin nombre';
  timestamp = new Date().toISOString();
  wa_phone_id = body.wa_phone_id || 'cli_001';
  canal = body.canal || 'whatsapp';
  message_id = '';
}

// Ignorar mensajes vacios
if (!mensaje || mensaje.trim() === '') {
  return [];
}

// Generar schema_name: solo letras, numeros y guion bajo
const schema_name = (wa_phone_id || 'clinica_demo')
  .replace(/-/g, '_')
  .replace(/[^a-zA-Z0-9_]/g, '')
  .toLowerCase();

return [{
  json: {
    numero,
    mensaje: mensaje.trim(),
    nombre,
    timestamp,
    wa_phone_id,
    canal,
    message_id,
    schema_name
  }
}];
